import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Центральная теория анти-хищничества","description":"","frontmatter":{},"headers":[],"relativePath":"ru/04-反掠夺主义核心论纲.md","filePath":"ru/04-反掠夺主义核心论纲.md","lastUpdated":null}'),i={name:"ru/04-反掠夺主义核心论纲.md"};function l(o,t,n,h,s,_){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="центральная-теория-анти-хищничества" tabindex="-1">Центральная теория анти-хищничества <a class="header-anchor" href="#центральная-теория-анти-хищничества" aria-label="Permalink to &quot;Центральная теория анти-хищничества&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>04</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Анти-хищничество, Критика хищничества, Симбиотическая альтернатива, Этическая граница, Системная революция</td></tr></tbody></table><h2 id="i-определение-и-проявления-хищничества" tabindex="-1">I. Определение и проявления хищничества <a class="header-anchor" href="#i-определение-и-проявления-хищничества" aria-label="Permalink to &quot;I. Определение и проявления хищничества&quot;">​</a></h2><p>Хищничество — это космическое видение и система культивации, центральными средствами которой являются безвозмездное присвоение, пожирание и эксплуатация Истока, энергии, удачи и ресурсов других жизней или плоскостей с целью достижения собственной эволюции или эволюции своей группы. Хищничество — не конкретная техника культивации, а фундаментальная позиция, пронизывающая философию культивации, социальные институты и цивилизационные отношения.</p><p>В истории Хэн Юаньчжоу хищничество проявлялось в следующих основных формах:</p><table tabindex="0"><thead><tr><th>Форма</th><th>Проявление</th><th>Вред</th></tr></thead><tbody><tr><td>Энергетическое хищничество</td><td>Прямое пожирание энергии культивации или Истока других жизней</td><td>Вызывает смерть жертвы или полную потерю культивации; циркуляция космической энергии разрывается</td></tr><tr><td>Хищничество удачи</td><td>Кража удачи других или рас тайными искусствами</td><td>Вызывает крах судьбы жертвы и упадок расы</td></tr><tr><td>Монополия методов</td><td>Несколько сект монополизируют методы культивации, обменивая передачу на лояльность и ресурсы</td><td>Вызывает окостенение классов; низшие существа теряют эволюционные пути</td></tr><tr><td>Колонизация плоскостей</td><td>Высшие плоскости завоёвывают низшие, грабя их ресурсы и население</td><td>Повреждает мембрану плоскости и разрушает её экосистемы</td></tr><tr><td>Духовное порабощение</td><td>Превращение других жизней в инструменты культивации через контроль души</td><td>Лишает порабощённого свободной воли, нарушая достоинство жизни</td></tr><tr><td>Истощение ресурсов</td><td>Безудержная эксплуатация ресурсов планеты или плоскости</td><td>Вызывает экологическое вымирание и ускорение космической энтропии</td></tr></tbody></table><h2 id="ii-фундаментальные-заблуждения-хищничества" tabindex="-1">II. Фундаментальные заблуждения хищничества <a class="header-anchor" href="#ii-фундаментальные-заблуждения-хищничества" aria-label="Permalink to &quot;II. Фундаментальные заблуждения хищничества&quot;">​</a></h2><p>Анти-хищничество считает, что хищничество содержит три фундаментальных заблуждения:</p><h3 id="_2-1-заблуждение-космического-видения-рассмотрение-вселеннои-как-конечных-охотничьих-угодии" tabindex="-1">2.1 Заблуждение космического видения: рассмотрение вселенной как конечных охотничьих угодий <a class="header-anchor" href="#_2-1-заблуждение-космического-видения-рассмотрение-вселеннои-как-конечных-охотничьих-угодии" aria-label="Permalink to &quot;2.1 Заблуждение космического видения: рассмотрение вселенной как конечных охотничьих угодий&quot;">​</a></h3><p>Хищническое космическое видение рассматривает вселенную как охотничьи угодья с конечными ресурсами, полагая, что эволюция должна быть игрой с нулевой суммой и что возвышение сильного должно происходить ценой жертвы слабого. Это видение игнорирует собственную «эволюционность» вселенной — вселенная не статичный контейнер ресурсов, а живое существо, способное к общему вознесению измерения через упорядоченный симбиоз. Когда хищники пожирают слабых, они потребляют не только энергию слабых, но и эволюционный потенциал вселенной в целом.</p><h3 id="_2-2-этическое-заблуждение-постановка-права-сильного-на-эволюцию-выше-права-слабого-на-выживание" tabindex="-1">2.2 Этическое заблуждение: постановка права сильного на эволюцию выше права слабого на выживание <a class="header-anchor" href="#_2-2-этическое-заблуждение-постановка-права-сильного-на-эволюцию-выше-права-слабого-на-выживание" aria-label="Permalink to &quot;2.2 Этическое заблуждение: постановка права сильного на эволюцию выше права слабого на выживание&quot;">​</a></h3><p>Хищничество принимает «сильный пожирает слабого» за естественный закон, полагая, что сильный имеет право и даже обязанность пожирать слабого. Это этическое видение смешивает естественный отбор и моральный выбор. В природе пожирание слабого сильным — бессознательный экологический закон; но в сознательных цивилизациях культивации сильный обладает способностью выбора и потому несёт ответственность выбора. Хищничество, замаскированное под «Путь Небес», — по сути, упаковка сильным собственной жадности как космического закона.</p><h3 id="_2-3-заблуждение-эффективности-вера-в-то-что-хищничество-—-самыи-быстрыи-путь-эволюции" tabindex="-1">2.3 Заблуждение эффективности: вера в то, что хищничество — самый быстрый путь эволюции <a class="header-anchor" href="#_2-3-заблуждение-эффективности-вера-в-то-что-хищничество-—-самыи-быстрыи-путь-эволюции" aria-label="Permalink to &quot;2.3 Заблуждение эффективности: вера в то, что хищничество — самый быстрый путь эволюции&quot;">​</a></h3><p>Хищничество утверждает, что это самый быстрый и эффективный путь эволюции. Однако в долгосрочной перспективе хищническая эволюция страдает серьёзным «потолком эффективности»: во-первых, энергия, полученная хищничеством, часто несёт остаточную волю исходного владельца, требуя огромных усилий на переплавку и очищение; во-вторых, хищнические акты провоцируют сопротивление жертв и их аффилированных групп, увеличивая внешние издержки культивации; в-третьих, долгосрочная зависимость от хищничества деградирует собственную истоковую эволюционную способность культиватора, приводя к застою, когда добыча недоступна; в-четвёртых, хищнические культиваторы часто сталкиваются с узким местом «нечистого Истока» при прорыве к верховному уровню, что затрудняет подлинное прикосновение к космическому Истоку.</p><h2 id="iii-центральные-положения-анти-хищничества" tabindex="-1">III. Центральные положения анти-хищничества <a class="header-anchor" href="#iii-центральные-положения-анти-хищничества" aria-label="Permalink to &quot;III. Центральные положения анти-хищничества&quot;">​</a></h2><p>Анти-хищничество не просто отрицает всякую конкуренцию и различие, но предлагает следующие центральные положения:</p><ol><li><strong>Эволюция может быть ненулевой суммой</strong>: через симбиотические циклы и сеть якорей эволюция Десяти Тысяч Рас может давать синергетические эффекты, достигая эволюционной эффективности, где целое превышает сумму частей.</li><li><strong>Конкуренция должна быть созидательной, а не разрушительной</strong>: анти-хищничество не против здоровой конкуренции, но конкуренция должна принимать форму повышения собственной созидательной способности, а не устранения хищнической способности противника.</li><li><strong>Ответственность сильного больше его прав</strong>: чем выше уровень культиватора, тем больше его ответственность перед симбиотической сетью, а не больше его право хищничать. Продвинутые культиваторы обязаны наставлять младших, поддерживать стабильность якорей и защищать цивилизационную безопасность.</li><li><strong>Ресурсы должны увеличиваться через созидание, а не распределяться через хищничество</strong>: центральный подход симбиотической цивилизации — увеличивать пирог, а не делить его, непрерывно создавая новые ресурсы культивации через технологический прогресс и применение законов.</li><li><strong>Анти-хищничество — не уравниловка</strong>: анти-хищничество выступает против незаработанного хищничества, а не против различий, возникающих из принципа «Больше Труда — Больше Награды». Симбиотическая цивилизация признаёт различия в эволюционных результатах, но настаивает, что различия должны проистекать из собственных усилий и вклада.</li></ol><h2 id="iv-институциональные-гарантии-анти-хищничества" tabindex="-1">IV. Институциональные гарантии анти-хищничества <a class="header-anchor" href="#iv-институциональные-гарантии-анти-хищничества" aria-label="Permalink to &quot;IV. Институциональные гарантии анти-хищничества&quot;">​</a></h2><p>Анти-хищничество — не только теоретическое положение; оно обеспечено серией институциональных гарантий:</p><ul><li><strong>Правовая гарантия</strong>: Симбиотическая Конституция и Антимонопольный закон прямо запрещают хищническое поведение; Симбиотический Суд имеет юрисдикцию над делами о хищничестве</li><li><strong>Механическая гарантия</strong>: Система Подряда, Связанного с Результатом, обеспечивает распределение ресурсов на основе вклада, а не насилия; сеть якорей отслеживает аномальные потоки энергии</li><li><strong>Системная гарантия</strong>: все Триста Изначальных Систем Культивации основаны на принципах симбиотической циркуляции; хищнических методов не существует</li><li><strong>Образовательная гарантия</strong>: Симбиотическая образовательная система делает анти-хищническую этику обязательным предметом, искореняя хищническую мысль в корне</li><li><strong>Надзорная гарантия</strong>: Собрание Республики Десяти Тысяч Рас учредило Комитет по анти-хищничеству, отвечающий за надзор и расследование хищнического поведения</li></ul><h2 id="v-политика-в-отношении-остаточных-хищнических-сил" tabindex="-1">V. Политика в отношении остаточных хищнических сил <a class="header-anchor" href="#v-политика-в-отношении-остаточных-хищнических-сил" aria-label="Permalink to &quot;V. Политика в отношении остаточных хищнических сил&quot;">​</a></h2><p>В отношении остаточных хищнических сил, всё ещё существующих во вселенной, симбиотическая цивилизация принимает политику «изоляции, трансформации и санкций»: хищники, ещё не причинившие серьёзного вреда, получают этическое образование и системную трансформацию с направлением к вступлению в симбиотическую систему; хищники, отказывающиеся от трансформации и продолжающие вредить симбиотическому порядку, подвергаются изоляции плоскости и ограничениям культивации; хищники, причинившие крупные катастрофы, подвергаются санкциям по закону. Симбиотическая цивилизация не выступает за борьбу с хищничеством путём хищничества; все санкции должны проходить через справедливый суд Симбиотического Суда.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Анти-хищничество — одна из теоретических краеугольных камней Симбиотической Цивилизации Якоря. Это не только критика старой хищнической системы, но и позитивное конструирование возможности симбиотической эволюции. Конечная цель анти-хищничества — не устранить сильных, а заставить силу сильных служить общей эволюции Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Декларация Симбиотической Цивилизации Якоря)</li><li>03-共生文明宪章 (Устав Симбиотической Цивилизации)</li><li>19-修炼伦理与边界 (Этика культивации и границы)</li></ul>',26)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
